// <auto-generated/>
using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows.Forms;
using CargoWise.EntityFramework;
using CargoWise.Integration;
using CargoWise.Types;
using Enterprise.Environment;
using Enterprise.Freight.OnlineSailingSchedules;
using Enterprise.ZArchitecture;
using Enterprise.ZArchitecture.Environment;
using Enterprise.ZArchitecture.GUI;

namespace Enterprise.Freight.GUI.OnlineSailingSchedules
{
	public partial class OnlineSchedulesForm : ZChildForm
	{
		public OnlineSchedulesForm(OnlineSchedules onlineSchedules)
			: base(onlineSchedules)
		{
			InitializeComponent();
			CreateFilterComponent();
		}

		OnlineSchedules OnlineSchedules => (OnlineSchedules)BusinessEntity;
		public override IBusiness BusinessEntity => selectedSchedules ?? base.BusinessEntity;
		OnlineSchedules selectedSchedules;

		internal OnlineSailingSchedulesFilterControl FilterControl { get; private set; }

		public event EventHandler<OnlineSailingSchedulesImportedEventArgs> SailingSchedulesImported;

		public bool AllowMultipleSelection { get; set; } = true;
		public bool SailingScheduleCreateFromJob { get; set; }

		public void SetFilterDefaults(OnlineSchedulesFilterStripBusinessObject.FilterDefaults filterDefaults)
		{
			var filterStripBizo = FilterControl.FilterBusinessObject as OnlineSchedulesFilterStripBusinessObject;
			if (filterStripBizo != null)
			{
				filterStripBizo.SetFilterVisibility();
				FilterControl.ResetFilterStrips();
				filterStripBizo.SetFilterSpecifiedDateRangeOptions();

				filterStripBizo.SetFilterDefaults(filterDefaults);
			}
		}

		void CloseButton_Click(object sender, EventArgs e)
		{
			Close();
		}

		void ImportButton_Click(object sender, EventArgs e)
		{
			if (!Env.Security.SailingScheduleNew.IsAllowed)
			{
				Globals.Message.ShowError(Env.Security.SailingScheduleNew.ErrorMessageForNotAllowed);
				return;
			}

			if (SailingScheduleCreateFromJob && !Env.Security.SailingScheduleCreateFromJob.IsAllowed)
			{
				Globals.Message.ShowError(Env.Security.SailingScheduleCreateFromJob.ErrorMessageForNotAllowed);
				return;
			}

			try
			{
				var selectedRoutes = FilterControl.FilteredGrid.SelectedElements.Cast<Route>().ToArray();
				if (selectedRoutes.Length == 0)
				{
					Globals.Message.ShowError(ResString.GetMultilingualString("f270d972-2548-4d12-8213-8e9c034518d8", "Please select an item from the grid."));
					return;
				}

				if (!AllowMultipleSelection && selectedRoutes.Length > 1)
				{
					Globals.Message.Show(ResString.GetMultilingualString("89fc9077-1cf0-460b-904a-0e2617ca188c", "Please select only one route."));
					return;
				}

				selectedSchedules = OnlineSchedules.CloneSelectedSchedules(selectedRoutes);

				var invalidDateCombinationErrorMessage = CheckDepartureAndArrivalTime(selectedRoutes);

				if (!invalidDateCombinationErrorMessage.IsEmpty)
				{
					Globals.Message.ShowError(ResString.GetMultilingualString("3353F8EF-6904-458F-BB26-E8CE29C216D4", "{0}", invalidDateCombinationErrorMessage));
					return;
				}

				if (FireSaveButton() == ContinueWithSave.Yes)
				{
					SailingSchedulesImported?.Invoke(this, new OnlineSailingSchedulesImportedEventArgs(selectedRoutes));

					ZString message = selectedSchedules.Routes.Count == 1
						? ResString.GetMultilingualString("0e9cd331-7148-4016-9d25-7eac1437e2a8", "1 schedule has been imported.")
						: ResString.GetMultilingualString("33dbef5f-7228-47e4-8645-450ba426efe8", "{0} schedules have been imported.",
							selectedSchedules.Routes.Count);

					Globals.Message.Show(message);

					if (!AllowMultipleSelection)
					{
						Close();
					}
				}
			}
			catch (ZSaveConcurrencyException)
			{
				try
				{
					ZExceptionReporting.ProcessWithSaveExceptionHandling(OnlineSchedules.Factory.Save, null, true);
				}
				catch (ZSaveConcurrencyException)
				{
					Globals.Message.Show(ResString.GetMultilingualString("a0e0eeeb-eaf7-467b-a020-df3f818d4fcd", @"While you have been working with this form, another user has made changes to the same schedules. Please run import again."));
				}
			}
			finally
			{
				selectedSchedules = null;
			}
		}

		ZString CheckDepartureAndArrivalTime(Route[] routes)
		{
			var reasonForNotGeneratedSailing = new List<ZString>();

			foreach (var route in routes)
			{
				foreach (var leg in route.Legs.Cast<Leg>())
				{
					if (leg.Departure > leg.Arrival)
					{
						reasonForNotGeneratedSailing.Add($"{leg.OriginPortUnloco} ({leg.Departure}) -> {leg.DestinationPortUnloco} ({leg.Arrival}): Arrival time cannot be before Departure time.");
					}
				}
			}

			return string.Join("\n", reasonForNotGeneratedSailing);
		}

		protected override void Save(ITransactionParticipant[] factories)
		{
			OnlineSchedules.CreateEnterpriseVoyages();
			base.Save(factories);
		}

		protected virtual OnlineSailingSchedulesFilterControl NewFilterControl(RoutesCollection routes, OnlineSchedulesFilterStripBusinessObject filterBO)
		{
			return new OnlineSailingSchedulesFilterControl(routes, filterBO);
		}

		void CreateFilterComponent()
		{
			var filterBO = new OnlineSchedulesFilterStripBusinessObject(OnlineSchedules);
			FilterControl = NewFilterControl(OnlineSchedules.Routes, filterBO);
			FilterPanel.Controls.Add(FilterControl);
			FilterControl.Dock = DockStyle.Fill;

			FilterControl.FilteredGrid.IsWholeRowSelectedOnClick = true;
			FilterControl.FilteredGrid.RemoveAction = RemoveAction.NoRemovePossible;

			FilterControl.PerformSearch += FilterControl_PerformSearch;
		}

		void FilterControl_PerformSearch(object sender, EventArgs e)
		{
			using (new ZWaitCursorChanger())
			{
				var filtersSelectedMultipleTimes = FilterControl.GetFiltersSelectedMultipleTimes();

				if (filtersSelectedMultipleTimes.Count > 0)
				{
					var errorMessage = ResString.GetMultilingualString("2756158E-4AA6-44AC-A420-CFFB7E2EE3B4", "A filter can be selected only once. The following filter(s) have been selected multiple times: {0}.", string.Join(", ", filtersSelectedMultipleTimes.ToArray()));
					Globals.Message.ShowError(errorMessage);
				}
				else
				{
					var onlineSchedulesFilterStripBusinessObject = (OnlineSchedulesFilterStripBusinessObject)FilterControl.FilterBusinessObject;
					OnlineSchedules.Request = onlineSchedulesFilterStripBusinessObject.BuildRequest();

					var validationMessage = OnlineSchedules.Request.Validate();
					if (!string.IsNullOrWhiteSpace(validationMessage))
					{
						Globals.Message.ShowError(validationMessage);
					}
					else
					{
						if (onlineSchedulesFilterStripBusinessObject.AreCarrierAndCarrierScacBothSelected)
						{
							var result = Globals.Message.Show(
								Res.GetString("94EFED9D-9F76-42E9-8FCE-77715B7023DF", "Both Carrier Code and Carrier SCAC filters are used. The Carrier SCAC filter will be applied by default."),
								string.Empty,
								MessageBoxButtons.OKCancel,
								MessageBoxIcon.Information);

							if (result != DialogResult.OK)
							{
								return;
							}
						}
						var notifications = new NotificationBuffer();
						OnlineSchedules.LoadRoutes(notifications);

						if (notifications.HasErrors)
						{
							Globals.Message.ShowError(notifications.AsString.TrimEnd('\r', '\n'));
						}
						else
						{
							if (notifications.HasWarnings)
							{
								Globals.Message.ShowWarning(notifications.AsString.TrimEnd('\r', '\n'));
							}

							if (!OnlineSchedules.Routes.Any())
							{
								Globals.Message.Show(Res.GetString("72261921-2a48-419e-97ad-bdf908d9f8fa", "There are no routes found by provided criteria."));
							}
						}
					}
				}
			}
		}
	}
}
